// Image cache — all bundled PNGs are embedded in asset_pack.generated.js
// as base64 data URLs. This bypasses every browser restriction around
// XHR/fetch/toDataURL on file:// origin (Chrome taints canvases when the
// source is another local file, making <img> + canvas unreliable).
//
// The pack is generated by tools/build_asset_pack.py.

/**
 * Preloading is a no-op because everything is already inlined at page
 * load. Kept as a function so build_deck.js can still call it safely.
 */
async function preloadPlanAssets(/* plan */) { /* noop */ }
